export function questionsForRole(role: string, projectContext?: string): QuestionDef[] {
  const base = QUESTION_BANK.filter((q) => q.roles.includes(role as any))
  const ideation = GENERIC_IDEATION_QUESTIONS.filter((q) => q.roles.includes(role as any))
  const withIdeation = [...base, ...ideation]
  if (!projectContext) return withIdeation

  const industryQuestions = questionsForIndustry(projectContext, role)
  // de-dupe by id in case of overlap
  const ids = new Set(withIdeation.map((q) => q.id))
  return [...withIdeation, ...industryQuestions.filter((q) => !ids.has(q.id))]
}

/**
 * Industry-specific question bank — the piece that was missing. Without
 * this, every project of any type got the exact same generic 9 questions
 * per role, regardless of whether it was a music app or a hospital
 * scheduling tool. Detected via keyword matching against the project name
 * (and document text, when a file was uploaded) — a rule-based stand-in
 * for a real project-type classifier, same as the rest of the "ML" in
 * this app right now.
 */
export const INDUSTRY_KEYWORDS: Record<string, string[]> = {
  music: ['music', 'song', 'stream', 'playlist', 'audio', 'artist', 'album', 'podcast'],
  ecommerce: ['shop', 'store', 'ecommerce', 'e-commerce', 'retail', 'cart', 'checkout', 'product catalog'],
  healthcare: ['patient', 'health', 'clinic', 'hospital', 'medical', 'diagnosis', 'appointment', 'ehr'],
  fintech: ['bank', 'payment', 'fintech', 'loan', 'invoice', 'wallet', 'transaction', 'ledger'],
  support: ['support', 'helpdesk', 'ticket', 'customer service', 'chatbot']
}

export function detectIndustries(text: string): string[] {
  const lowered = text.toLowerCase()
  return Object.entries(INDUSTRY_KEYWORDS)
    .filter(([, keywords]) => keywords.some((k) => lowered.includes(k)))
    .map(([industry]) => industry)
}

