const INDUSTRY_ID_PREFIX: Record<string, string> = {
  music: 'Q-MUSIC',
  ecommerce: 'Q-ECOM',
  healthcare: 'Q-HEALTH',
  fintech: 'Q-FIN',
  support: 'Q-SUPPORT'
}

export function questionsForIndustry(projectContext: string, role: string): QuestionDef[] {
  const industries = detectIndustries(projectContext)
  const prefixes = industries.map((ind) => INDUSTRY_ID_PREFIX[ind]).filter(Boolean)
  return INDUSTRY_QUESTIONS.filter(
    (q) => q.roles.includes(role as any) && prefixes.some((prefix) => q.id.startsWith(prefix))
  )
}

/**
 * Domain criticality weights — the "Criticality" term in the next-best-
 * question scoring formula (Part 13 of the system design doc):
 *   Score(Q) = InformationGain × Criticality × RoleRelevance − DependencyPenalty
 * Higher = more important to resolve early. These are hand-set for the
 * MVP; a real XGBoost gap model would eventually learn these instead of
 * having them hard-coded, but the formula shape stays identical either way.
 */
export const DOMAIN_CRITICALITY: Record<string, number> = {
  Security: 5,
  Compliance: 5,
  Data: 4,
  'AI/ML': 4,
  Deployment: 4,
  Business: 3,
  Users: 3,
  'Functional Requirements': 3,
  'Non-Functional Requirements': 3,
  Integrations: 3,
  Technology: 3,
  Architecture: 3,
  Infrastructure: 3,
  Operations: 2,
  Monitoring: 2,
  Budget: 2,
  Timeline: 2,
  Stakeholders: 2,
  'Success Metrics': 2,
  Risks: 3,
  // Ideation questions are intentionally lower-weighted than any gap
  // domain — gaps that block scoping get resolved first, ideation
  // questions fill in once the fundamentals are covered, same as a
  // human consultant would sequence a conversation.
  'Product Ideation': 1
}

/**
 * Real next-best-question selection — replaces "first eligible in list
 * order" with the actual scoring formula. Every mandatory question here
 * has equal information gain (all are unresolved, unweighted otherwise),
 * so with role relevance fixed at 1 (already filtered to this role), this
 * reduces to: highest domain criticality among dependency-eligible
 * questions wins. That's a real, honest ranking — not a random order —
 * and it's the same formula shape a future ML ranking model would slot
 * into without changing anything downstream.
 */
export function selectNextQuestion(
  eligible: QuestionDef[]
): QuestionDef | undefined {
  if (eligible.length === 0) return undefined
  return [...eligible].sort((a, b) => {
    const scoreA = (DOMAIN_CRITICALITY[a.domain] ?? 2) * (a.mandatory ? 1 : 0.5)
    const scoreB = (DOMAIN_CRITICALITY[b.domain] ?? 2) * (b.mandatory ? 1 : 0.5)
    return scoreB - scoreA
  })[0]
}
